;GOSUB line
;
EXEC_GOSUB:	CALL	ITEMI			;LINE NUMBER
EXEC_GOSUB1:	PUSH	IY			;TEXT POINTER
	CALL	CHECK			;CHECK ROOM
	CALL	EXEC_GOTO1			;SAVE MARKER
EXEC_GOSCHK:	EQU	$
;
;RETURN
;
EXEC_RETURN:	POP	DE			;MARKER
	LD	HL,EXEC_GOSCHK
	OR	A
	SBC	HL,DE
	POP	IY
	JR	Z,EXEC_XEQGO2
	LD	A,38
	JR	EXEC_ERROR2			;"No GOSUB"
;
;REPEAT
;
EXEC_REPEAT:	PUSH	IY
	CALL	CHECK
	CALL	XEQ
EXEC_REPCHK:	EQU	$
;
;UNTIL expr
;
EXEC_UNTIL:	POP	BC
	PUSH	BC
	LD	HL,EXEC_REPCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_UNTIL1
	LD	A,3
	CALL	EXEC_RESLOC
	JR	NZ,EXEC_UNTIL
	LD	A,43
	JR	EXEC_ERROR2			;"Not in a REPEAT loop"
;
EXEC_UNTIL1:	CALL	EXPRI
	CALL	TEST
	POP	BC
	POP	DE
	JR	NZ,EXEC_XEQGO2			;TRUE
	PUSH	DE
	PUSH	BC
	PUSH	DE
	POP	IY
EXEC_XEQGO2:	JP	XEQ
;
;FOR var = expr TO expr [STEP expr]
;
EXEC_FOR:	CALL	EXEC_ASSIGN
	JR	NZ,EXEC_FORVAR		;"FOR variable"
	PUSH	AF			;SAVE TYPE
	LD	A,(IY)
	CP	EXEC_TTO
	LD	A,36
	JR	NZ,EXEC_ERROR2		;"No TO"
	INC	IY
	PUSH	IX
	CALL	EXPRN			;LIMIT
	POP	IX
	POP	AF
	LD	B,A			;TYPE
	PUSH	BC			;SAVE ON STACK
	PUSH	HL
	LD	HL,0
	LD	C,H
	EXX
	PUSH	HL
	LD	HL,1			;PRESET STEP
	EXX
	LD	A,(IY)
	CP	EXEC_TSTEP
	JR	NZ,EXEC_FOR1
	INC	IY
	PUSH	IX
	CALL	EXPRN			;STEP
	POP	IX
EXEC_FOR1:	LD	B,8			;FPP '>'
	BIT	7,H
	JR	NZ,EXEC_FOR2			;STEP SIGN
	LD	B,12			;FPP '<'
EXEC_FOR2:	PUSH	BC
	PUSH	HL
	EXX
	PUSH	HL
	EXX
	PUSH	IY			;SAVE TEXT POINTER
	PUSH	IX			;LOOP VARIABLE
	CALL	CHECK
	CALL	XEQ
EXEC_FORCHK:	EQU	$
;
;NEXT [var[,var...]]
;
EXEC_NEXT:	POP	BC			;MARKER
	LD	HL,EXEC_FORCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_NEXT2
	PUSH	BC
	LD	A,3
	CALL	EXEC_RESLOC
	JR	NZ,EXEC_NEXT
	LD	A,32
	JR	EXEC_ERROR3			;"Not in a FOR loop"
;
EXEC_NEXT2:	CALL	TERMQ
	POP	HL
	PUSH	HL
	PUSH	BC
	PUSH	HL
	CALL	NZ,GETVAR		;VARIABLE
	POP	DE
	EX	DE,HL
	OR	A
EXEC_NEXT0:	SBC	HL,DE
	JR	NZ,EXEC_NEXT1
	PUSH	DE
	LD	IX,6+2
	ADD	IX,SP
	CALL	DLOAD5			;STEP
	LD	A,(IX+11)		;TYPE
	POP	IX
	CALL	LOADN			;LOOP VARIABLE
	PUSH	AF
	LD	A,'+' AND 0FH
	CALL	FPP			;ADD STEP
	JR	C,EXEC_ERROR3
	POP	AF			;RESTORE TYPE
	CALL	STOREN			;UPDATE VARIABLE
	LD	IX,12
	ADD	IX,SP
	CALL	DLOAD5			;LIMIT
	LD	A,(IX-1)
	CALL	FPP			;TEST AGAINST LIMIT
	JR	C,EXEC_ERROR3
	INC	H
	JR	NZ,EXEC_LOOP			;KEEP LOOPING
	LD	HL,18
	ADD	HL,SP
	LD	SP,HL
	CALL	NLIST
	JR	EXEC_NEXT
;
EXEC_LOOP:	POP	BC
	POP	DE
	POP	IY
	PUSH	IY
	PUSH	DE
	PUSH	BC
	JP	XEQ
;
EXEC_NEXT1:	LD	HL,18
	ADD	HL,SP
	LD	SP,HL			;"POP" THE STACK
	POP	BC
	LD	HL,EXEC_FORCHK
	SBC	HL,BC
	POP	HL			;VARIABLE POINTER
	PUSH	HL
	PUSH	BC
	JR	Z,EXEC_NEXT0
	LD	A,33
EXEC_ERROR3:	JP	ERROR			;"Can't match FOR"
;
;FNname
;N.B. ENTERED WITH A <> TON
;
FN:	PUSH	AF			;MAKE SPACE ON STACK
	CALL	EXEC_PROC1
EXEC_FNCHK:	EQU	$
;
;PROCname
;N.B. ENTERED WITH A = ON PROC FLAG
;
EXEC_PROC:	PUSH	AF			;MAKE SPACE ON STACK
	CALL	EXEC_PROC1
EXEC_PROCHK:	EQU	$
EXEC_PROC1:	CALL	CHECK
	DEC	IY
	PUSH	IY
	CALL	GETDEF
	POP	BC
	JR	Z,EXEC_PROC4
	LD	A,30
	JR	C,EXEC_ERROR3		;"Bad call"
	PUSH	BC
	LD	HL,(PAGE)
EXEC_PROC2:	LD	A,EXEC_TDEF
	CALL	EXEC_SEARCH			;LOOK FOR "DEF"
	JR	C,EXEC_PROC3
	PUSH	HL
	POP	IY
	INC	IY			;SKIP DEF
	CALL	NXT
	CALL	GETDEF
	PUSH	IY
	POP	DE
	JR	C,EXEC_PROC6
	CALL	NZ,CREATE
	PUSH	IY
	POP	DE
	LD	(HL),E
	INC	HL
	LD	(HL),D			;SAVE ADDRESS
EXEC_PROC6:	EX	DE,HL
	LD	A,EXEC_CR
	LD	B,A
	CPIR	;SKIP TO END OF LINE
	JR	EXEC_PROC2
EXEC_PROC3:	POP	IY			;RESTORE TEXT POINTER
	CALL	GETDEF
	LD	A,29
	JR	NZ,EXEC_ERROR3		;"No such FN/PROC"
EXEC_PROC4:	LD	E,(HL)
	INC	HL
	LD	D,(HL)			;GET ADDRESS
	LD	HL,2
	ADD	HL,SP
	CALL	NXT			;ALLOW SPACE BEFORE (
	PUSH	DE			;EXCHANGE DE,IY
	EX	(SP),IY
	POP	DE
	CP	'('			;ARGUMENTS?
	JP	NZ,EXEC_PROC5
	CALL	NXT			;ALLOW SPACE BEFORE (
	CP	'('
	JP	NZ,SYNTAX		;"Syntax error"
	PUSH	IY
	POP	BC			;SAVE IY IN BC
	EXX
	EX	AF,AF'
	XOR	A			;INITIALISE RETURN COUNT
	EX	AF,AF'
	CALL	EXEC_SAVLOC			;SAVE DUMMY VARIABLES
	EX	AF,AF'
	OR	A
	JR	Z,EXEC_RETCHK		;NO RETURNS
	PUSH	HL
	NEG
	LD	L,A
	NEG
	LD	H,-1			;HL = -RETURNS
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,HL			;-RETURNS * 8
	EX	(SP),HL
	POP	IX
	ADD	IX,SP
	LD	SP,IX
	PUSH	AF			;PUSH RETURN COUNT
	CALL	EXEC_RETCHK			;PUSH MARKER
EXEC_RETCHK:	EX	AF,AF'
	CALL	BRAKET			;CLOSING BRACKET
	EXX
	PUSH	BC
	POP	IY			;RESTORE IY
	PUSH	HL
	CALL	EXEC_ARGUE			;TRANSFER ARGUMENTS
	POP	HL
;
; If any of the dummy arguments is the same as a passed-by-reference
; variable, then it must not be restored on exit (it would overwrite
; the wanted returned values), therefore search the saved values on
; the stack and if a match is found set bit 4 of the type.  On exit
; from the FN/PROC this will prevent the dummies from being restored.
;
	EX	(SP),HL
	OR	A
	LD	BC,EXEC_RETCHK
	SBC	HL,BC
	ADD	HL,BC
	EX	(SP),HL
	JR	NZ,EXEC_PROC5		;No RETURNs
;
	PUSH	DE
	PUSH	HL
	LD	HL,7			;Skip two PUSHes and RETCHK
	ADD	HL,SP
	LD	A,(HL)			;RETURN count
	INC	HL
	PUSH	HL
	POP	IX			;Address RETURNs table
EXEC_PROC0:	LD	E,A
	LD	D,0
	EX	DE,HL
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,DE			;HL addresses SAVLOC stack
	INC	HL
	INC	HL			;Bump past LOCCHK
EXEC_PROC7:	LD	E,(HL)
	INC	HL
	LD	D,(HL)			;DE = SAVLOC VARPTR
	INC	HL
	LD	C,(HL)			;Length (if string)
	INC	HL
	LD	B,(HL)			;Variable type
;
; Scan RETURNs table for VARPTR match
;
	PUSH	BC			;Save type
	PUSH	HL
	PUSH	IX
	LD	B,A			;B = RETURN count
EXEC_PROC8:	LD	L,(IX+4)
	LD	H,(IX+5)		;HL = RETURNed VARPTR
	OR	A
	SBC	HL,DE
	JR	Z,EXEC_PROC9
	EX	DE,HL
	LD	DE,8
	ADD	IX,DE
	EX	DE,HL
	DJNZ	EXEC_PROC8
EXEC_PROC9:	POP	IX
	POP	HL
	POP	BC			;Restore type
;
; If match, set bit 4 of type:
;
	JR	NZ,EXEC_PROCA
	SET	4,(HL)			;Flag don't restore
;
; Increment past stacked data:
;
EXEC_PROCA:	LD	DE,3
	BIT	6,B
	JR	NZ,EXEC_PROCB		;Whole array
	LD	E,5
	BIT	7,B
	JR	Z,EXEC_PROCB			;Numeric
	LD	E,C
	INC	DE
EXEC_PROCB:	ADD	HL,DE
	LD	C,(HL)
	INC	HL
	LD	B,(HL)
	INC	HL			; BC = marker ?
	EX	DE,HL
	LD	HL,EXEC_LOCCHK
	OR	A
	SBC	HL,BC
	EX	DE,HL
	JR	Z,EXEC_PROC7			;Another
	POP	HL
	POP	DE
;
EXEC_PROC5:	LD	(HL),E			;SAVE "RETURN ADDRESS"
	INC	HL
	LD	A,(HL)
	LD	(HL),D
	CP	EXEC_TON			;WAS IT "ON PROC" ?
	JR	NZ,EXEC_XEQGO
	PUSH	DE
	EX	(SP),IY
	CALL	EXEC_SPAN			;SKIP REST OF ON LIST
	EX	(SP),IY
	POP	DE
	LD	(HL),D
	DEC	HL
	LD	(HL),E
EXEC_XEQGO:	JP	XEQ
;
EXEC_LOCERR:	INC	IY
	JR	EXEC_XEQGO
;
;LOCAL DATA
;
EXEC_LOCDAT:	INC	IY
	LD	HL,(DATPTR)
	PUSH	HL
	LD	A,40H
	PUSH	AF
	LD	HL,DATPTR
	PUSH	HL
	LD	HL,EXEC_LOCCHK
	PUSH	HL
	JR	EXEC_XEQGO
;
;LOCAL var[,var...]
;
EXEC_LOCAL:	CP	EXEC_TERROR
	JR	Z,EXEC_LOCERR
	CP	EXEC_TDATA
	JR	Z,EXEC_LOCDAT
	POP	BC
	PUSH	BC
	LD	HL,EXEC_FNCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_LOCAL1
	LD	HL,EXEC_PROCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_LOCAL1
	LD	HL,EXEC_LOCCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_LOCAL1
	LD	HL,EXEC_ARRCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_LOCAL1
	LD	HL,EXEC_RETCHK
	OR	A
	SBC	HL,BC
	LD	A,12
	JP	NZ,ERROR		;"Not LOCAL"
EXEC_LOCAL1:	PUSH	IY
	POP	BC
	EXX
	DEC	IY
	CALL	EXEC_SAVLOC
	EXX
	PUSH	BC
	POP	IY
EXEC_LOCAL2:	CALL	GETVAR
	JP	NZ,SYNTAX
	BIT	6,A			;ARRAY?
	JR	NZ,EXEC_LOCAL4
	OR	A			;TYPE
	EX	AF,AF'
	CALL	ZERO
	EX	AF,AF'
	PUSH	AF
	CALL	P,STOREN		;ZERO
	POP	AF
	LD	E,C
	CALL	M,EXEC_STORES
EXEC_LOCAL3:	CALL	NLIST
	JR	EXEC_LOCAL2
;
EXEC_LOCAL4:	LD	(IX+0),1		;FLAG LOCAL ARRAY
	LD	(IX+1),0
	JR	EXEC_LOCAL3
;
;ENDPROC
;
EXEC_ENDPRO:	POP	BC
	LD	HL,EXEC_PROCHK		;PROC MARKER
	XOR	A
	SBC	HL,BC
	JR	Z,EXEC_ENDPR1
	PUSH	BC			;PUT BACK
	CALL	EXEC_RESLOC
	JR	NZ,EXEC_ENDPRO
	LD	A,13
	JP	ERROR			;"No PROC"
;
EXEC_ENDPR1:	POP	IY
EXEC_XEQGO6:	JP	XEQ
;
;INPUT #channel,var,var...
;
EXEC_INPUTN:	CALL	CHNL			;E = CHANNEL NUMBER
EXEC_INPN1:	CALL	NLIST
	PUSH	DE
	CALL	VAR
	POP	DE
	PUSH	AF			;SAVE TYPE
	PUSH	HL			;VARPTR
	OR	A
	JP	M,EXEC_INPN2			;STRING
	CALL	OSBGET
	EXX
	LD	L,A
	EXX
	CALL	OSBGET
	EXX
	LD	H,A
	EXX
	CALL	OSBGET
	LD	L,A
	CALL	OSBGET
	LD	H,A
	CALL	OSBGET
	LD	C,A
	POP	IX
	POP	AF			;RESTORE TYPE
	PUSH	DE			;SAVE CHANNEL
	CALL	STOREN
	POP	DE
	JR	EXEC_INPN1
EXEC_INPN2:	LD	HL,ACCS
EXEC_INPN3:	CALL	OSBGET
	CP	EXEC_CR
	JR	Z,EXEC_INPN4
	LD	(HL),A
	INC	L
	JR	NZ,EXEC_INPN3
EXEC_INPN4:	POP	IX
	POP	AF
	PUSH	DE
	EX	DE,HL
	CALL	STACCS
	POP	DE
	JR	EXEC_INPN1
;
;INPUT ['][SPC(x)][TAB(x[,y])]["prompt",]var[,var...]
;INPUT LINE [SPC(x)][TAB(x[,y])]["prompt",]var[,var...]
;
EXEC_INPUT:	CP	'#'
	JR	Z,EXEC_INPUTN
	LD	C,0			;FLAG PROMPT
	CP	EXEC_TLINE
	JR	NZ,EXEC_INPUT0
	INC	IY			;SKIP "LINE"
	LD	C,80H
EXEC_INPUT0:	LD	HL,BUFFER
	LD	(HL),EXEC_CR			;INITIALISE EMPTY
EXEC_INPUT1:	CALL	TERMQ
	JR	Z,EXEC_XEQGO6		;DONE
	INC	IY
	CP	','
	JR	Z,EXEC_INPUT3		;SKIP COMMA
	CP	';'
	JR	Z,EXEC_INPUT3
	PUSH	HL			;SAVE BUFFER POINTER
	CP	'"'
	JR	NZ,EXEC_INPUT6
	PUSH	BC
	CALL	CONS
	POP	BC
	CALL	EXEC_PTEXT			;PRINT PROMPT
	JR	EXEC_INPUT9
EXEC_INPUT6:	CALL	EXEC_FORMAT			;SPC, TAB, '
	JR	NZ,EXEC_INPUT2
EXEC_INPUT9:	POP	HL
	SET	0,C			;FLAG NO PROMPT
	JR	EXEC_INPUT0
EXEC_INPUT2:	DEC	IY
	PUSH	BC
	CALL	VAR
	POP	BC
	POP	HL
	PUSH	AF			;SAVE TYPE
	LD	A,(HL)
	INC	HL
	CP	EXEC_CR			;BUFFER EMPTY?
	CALL	Z,EXEC_REFILL
	BIT	7,C
	PUSH	AF
	CALL	NZ,EXEC_LINES
	POP	AF
	CALL	Z,EXEC_FETCHS
	POP	AF			;RESTORE TYPE
	PUSH	BC
	PUSH	HL
	OR	A
	JP	M,EXEC_INPUT4		;STRING
	PUSH	AF
	PUSH	IX
	CALL	VAL0
	POP	IX
	POP	AF
	CALL	STOREN
	JR	EXEC_INPUT5
EXEC_INPUT4:	CALL	STACCS
EXEC_INPUT5:	POP	HL
	POP	BC
EXEC_INPUT3:	RES	0,C
	JR	EXEC_INPUT1
;
EXEC_REFILL:	BIT	0,C
	JR	NZ,EXEC_REFIL0		;NO PROMPT
	LD	A,'?'
	CALL	OUTCHR			;PROMPT
	LD	A,' '
	CALL	OUTCHR
EXEC_REFIL0:	LD	HL,BUFFER
	PUSH	BC
	PUSH	HL
	PUSH	IX
	CALL	OSLINE
	POP	IX
	POP	HL
	POP	BC
	LD	B,A			;POS AT ENTRY
	XOR	A
	LD	(COUNT),A
	CP	B
	RET	Z
EXEC_REFIL1:	LD	A,(HL)
	CP	EXEC_CR
	RET	Z
	INC	HL
	DJNZ	EXEC_REFIL1
	RET
;
;READ var[,var...]
;
EXEC_READ:	CP	'#'
	JP	Z,EXEC_INPUTN
	LD	HL,(DATPTR)
EXEC_READ0:	LD	A,(HL)
	CP	':'
	CALL	Z,EXEC_REFIL1
	INC	HL			;SKIP COMMA OR "DATA"
	CP	EXEC_CR			;END OF DATA STMT?
	CALL	Z,EXEC_GETDAT
	PUSH	HL
	CALL	VAR
	POP	HL
	OR	A
	JP	M,EXEC_READ1			;STRING
	PUSH	HL
	EX	(SP),IY
	PUSH	AF			;SAVE TYPE
	PUSH	IX
	CALL	EXPRN
	POP	IX
	POP	AF
	CALL	STOREN
	EX	(SP),IY
	JR	EXEC_READ2
EXEC_READ1:	CALL	EXEC_FETCHS
	PUSH	HL
	CALL	STACCS
EXEC_READ2:	POP	HL
	LD	(DATPTR),HL
	CALL	NLIST
	JR	EXEC_READ0
;
EXEC_GETDAT:	CALL	EXEC_DSRCH
	INC	HL
	RET	NC
	LD	A,42
	JR	EXEC_ERROR4			;"Out of DATA"
;
;IF expr statement
;IF expr THEN statement [ELSE statement]
;IF expr THEN line [ELSE line]
;IF expr THEN
;
EXEC_IF:	CALL	EXPRI
	CALL	TEST
	JR	Z,EXEC_IFNOT			;FALSE
	LD	A,(IY)
	CP	EXEC_TTHEN
	JP	NZ,XEQ
EXEC_IF0:	INC	IY			;SKIP "THEN"
	LD	A,(IY)
	CP	';'
	JR	Z,EXEC_IF0
EXEC_IF1:	CALL	NXT
	CP	EXEC_TLINO
	JP	NZ,XEQ			;STATEMENT FOLLOWS
	JP	EXEC_GOTO			;LINE NO. FOLLOWS
;
EXEC_IFELSE:	LD	A,(IY)
	INC	IY
	CP	';'
	JR	NZ,EXEC_IFNEXT
	JR	EXEC_IFTHEN
;
EXEC_IF2:	CALL	EXEC_QUOTE			;SKIP STRING
EXEC_IFNOT:	LD	A,(IY)
	INC	IY
EXEC_IFNEXT:	CP	'"'
	JR	Z,EXEC_IF2			;QUOTED STRING
	CP	EXEC_TREM
	JP	Z,EXEC_REM			;REM
	CP	EXEC_CR
	JP	Z,EXEC_XEQ0			;END OF LINE
	CP	EXEC_TELSE
	JR	Z,EXEC_IF1			;ELSE CLAUSE
	CP	EXEC_TTHEN
	JR	NZ,EXEC_IFNOT		;TRY FOR END AGAIN
EXEC_IFTHEN:	LD	A,(IY)
	CP	EXEC_CR
	JR	NZ,EXEC_IFELSE
	LD	BC,EXEC_TELSE
	LD	DE,EXEC_TENDIF*256+EXEC_TTHEN
	INC	IY
	CALL	EXEC_NSCAN
	JP	Z,EXEC_XEQ1
EXEC_NENDIF:	LD	A,49
EXEC_ERROR4:	JP	ERROR			;"Missing ENDIF"
;
; ELSE (multi-line)
;
EXEC_MELSE:	LD	BC,-3
	ADD	IY,BC
	LD	BC,EXEC_TENDIF
	LD	DE,EXEC_TENDIF*256+EXEC_TTHEN
	CALL	EXEC_NSCAN
	JR	NZ,EXEC_NENDIF
EXEC_XEQGO7:	JP	XEQ
;
; WHEN and OTHERWISE:
;
EXEC_WHEN:	LD	BC,-3
	ADD	IY,BC
	LD	BC,EXEC_TENDCASE
	LD	DE,EXEC_TENDCASE*256+EXEC_TOF
	CALL	EXEC_NSCAN
	JR	Z,EXEC_XEQGO7
	LD	A,47
	JR	EXEC_ERROR4			;"Missing ENDCASE"
;
; CASE
;
EXEC_CASE:	CALL	EXPR			;String or numeric
	EX	AF,AF'
	LD	B,0			;Flag numeric
	JP	P,EXEC_CASE6			;numeric
	CALL	PUSHS			;put string on stack
	POP	BC			;C = length
	LD	B,1			;Flag string
EXEC_CASE6:	LD	A,(IY)
	INC	IY
	CP	EXEC_TOF
	LD	A,37
	JR	NZ,EXEC_ERROR4		;"Missing OF"
	LD	A,(IY)
	INC	IY			;Address line-length byte
	CP	EXEC_CR
	LD	A,48
	JR	NZ,EXEC_ERROR4		;"OF not last"
EXEC_CASE1:	XOR	A			;Level
EXEC_CASE0:	EXX
	PUSH	HL			;Push to stack
	EXX
	PUSH	HL
	PUSH	BC
	LD	L,A			;Level
	LD	BC,EXEC_TOTHERWISE*256+EXEC_TWHEN
	LD	DE,EXEC_TENDCASE*256+EXEC_TOF
	CALL	EXEC_NSCAN1
	POP	BC			;Restore from stack
	POP	HL
	EXX
	POP	HL
	EXX
	LD	A,47
	JP	NZ,ERROR		;Missing ENDCASE
	LD	A,(IY-1)
	CP	EXEC_TENDCASE
	JR	Z,EXEC_CASE9
	CP	EXEC_TOTHERWISE
	JR	Z,EXEC_CASE9
EXEC_CASE4:	BIT	0,B			;Numeric or string?
	JR	NZ,EXEC_CASE3
	PUSH	BC			;Type/exponent/length 
	PUSH	HL			;MS 32 bits
	EXX
	PUSH	HL			;LS 32 bits
	EXX
	CALL	EXPRN
	LD	IX,0
	ADD	IX,SP			;Address stack
	EXX
	LD	E,(IX+0)		;Get LS 32-bits
	LD	D,(IX+1)
	EXX
	LD	E,(IX+2)
	LD	D,(IX+3)		;Get MS 32-bits
	LD	B,(IX+4)		;Get exponent
	LD	A,9
	CALL	FPP			;In case integer vs float
	LD	A,L
	OR	A			;NZ if equal
	EXX
	POP	HL
	EXX
	POP	HL
	POP	BC
	JR	NZ,EXEC_CASE5		;Match found
EXEC_CASE2:	LD	A,(IY)
	INC	IY
	CP	','
	JR	Z,EXEC_CASE4			;Not found, try another
	EXX
	PUSH	IY
	EX	(SP),HL
	LD	A,EXEC_CR
	LD	B,A
	CPIR	;Find CR
	EX	(SP),HL
	POP	IY
	EXX
	LD	A,(IY-2)		;Last token in previous line
	CP	EXEC_TOF			;CASE statement in WHEN line
	JR	NZ,EXEC_CASE1
	LD	A,1
	JR	EXEC_CASE0
;
;Finished, level stack if string:
;
EXEC_CASE9:	BIT	0,B
	JR	Z,EXEC_XEQGO5
	LD	H,0
	LD	L,C
	ADD	HL,SP
	LD	SP,HL
	JR	EXEC_XEQGO5
;
;Matched, so skip any more expressions:
;
EXEC_CASE5:	CALL	NXT
	CP	','
	JR	NZ,EXEC_CASE9		;End of list
	INC	IY
	PUSH	BC			;Save type and string length
	CALL	EXPR			;Evaluate but discard
	POP	BC
	JR	EXEC_CASE5
;
;String compare:
;
EXEC_CASE3:	PUSH	BC
	CALL	EXPRS
	POP	BC
	LD	HL,0
	ADD	HL,SP
	LD	B,E
	LD	DE,ACCS
	PUSH	BC
	CALL	SCP			;String compare
	POP	BC
	LD	B,1
	JR	NZ,EXEC_CASE2
	JR	EXEC_CASE5
;
; WHILE
;
EXEC_WHILE:	PUSH	IY			;Save current position
	CALL	CHECK
	CALL	EXEC_WHICHK			;Push marker
EXEC_WHICHK:	CALL	EXPRI
	CALL	TEST
	JR	NZ,EXEC_XEQGO5
	POP	BC			;Pop marker
	POP	BC			;Level stack
	LD	BC,EXEC_TWHILE+EXEC_TENDWHILE*256
	LD	D,1
	CALL	EXEC_WSRCH
EXEC_XEQGO5:	JP	XEQ
;
; ENDWHILE
;
EXEC_ENDWHI:	POP	BC			;Marker
	POP	DE			;Saved text pointer
	PUSH	DE
	PUSH	BC
	OR	A
	LD	HL,EXEC_WHICHK
	SBC	HL,BC
	JR	Z,EXEC_ENDWH1
	LD	A,3
	CALL	EXEC_RESLOC
	JR	NZ,EXEC_ENDWHI
	LD	A,46
	JR	EXEC_ERROR5			;"Not in a WHILE loop"
;
EXEC_ENDWH1:	PUSH	IY
	LD	IY,0
	ADD	IY,DE
	CALL	EXPRI
	CALL	TEST
	POP	DE			;Text pointer
	JR	NZ,EXEC_XEQGO5
	POP	BC			;Junk marker
	POP	BC			;Junk pointer
	LD	IY,0
	ADD	IY,DE
	JR	EXEC_XEQGO5
;
;CLS
;
EXEC_CLS:	CALL	CLRSCN
	XOR	A
	LD	(COUNT),A
	JR	EXEC_XEQGO5
;
;STOP
;
EXEC_STOP:	CALL	TELL
	DEFB	EXEC_CR
	DEFB	EXEC_LF
	DEFB	EXEC_TSTOP
	DEFB	0
	CALL	SETLIN			;FIND CURRENT LINE
	CALL	SAYLN
	CALL	CRLF
	JP	CLOOP
;
;REPORT
;
EXEC_REPOR:	CALL	REPORT
	JR	EXEC_XEQGO5
;
;CLEAR
;
EXEC_CLR:	CALL	CLEAR
	LD	HL,(PAGE)
	JR	EXEC_RESTR1
;
;RESTORE DATA / ERROR / LOCAL
;
EXEC_RESDEL:	INC	IY			;Skip DATA / ERROR / LOCAL
	LD	A,C			;Save error code
	EX	AF,AF'
	LD	A,B			;1=DATA, 2=ERROR, 0=LOCAL
	CALL	EXEC_RESLOC
	JR	NZ,EXEC_XEQGO5
	EX	AF,AF'			;Get error code
	DEFB	21H
EXEC_NOLINE:	LD	A,41			;'No such line'
EXEC_ERROR5:	JP	ERROR
;
;RESTORE [line | +n | DATA | ERROR | LOCAL]
;
EXEC_RESTOR:	CP	EXEC_TERROR
	LD	BC,200H + 53		;'ON ERROR not LOCAL'
	JR	Z,EXEC_RESDEL
	CP	EXEC_TDATA
	LD	BC,100H + 54		;'DATA not LOCAL'
	JR	Z,EXEC_RESDEL
	CP	EXEC_TLOCAL
	LD	BC,12			;'Not in a FN or PROC'
	JR	Z,EXEC_RESDEL
	CP	'+'
	JR	Z,EXEC_RESREL
	LD	HL,(PAGE)
	CALL	TERMQ
	JR	Z,EXEC_RESTR1
	CALL	ITEMI
	EXX
	CALL	FINDL			;SEARCH FOR LINE
	JR	NZ,EXEC_NOLINE
EXEC_RESTR1:	CALL	EXEC_DSRCH
	LD	(DATPTR),HL
	JP	XEQ
;
EXEC_RESREL:	CALL	EXPRI
	EXX
	EX	DE,HL
	PUSH	IY
	POP	HL
	LD	A,EXEC_CR
	LD	B,A
	CPIR	;FIND LINE END
	DEC	E
	JR	Z,EXEC_RESTR1
	JP	M,EXEC_RESTR1
	XOR	A
	LD	B,A
EXEC_RESTR2:	LD	C,(HL)
	CP	C
	JR	Z,EXEC_NOLINE
	ADD	HL,BC
	DEC	E
	JR	NZ,EXEC_RESTR2
	JR	EXEC_RESTR1
;
;PTR#channel=expr
;PAGE=expr
;TIME=expr
;LOMEM=expr
;HIMEM=expr
;
EXEC_PTR:	CALL	CHANEL
	CALL	EXEC_EQUALS
	LD	A,E
	PUSH	AF
	CALL	EXPRI
	PUSH	HL
	EXX
	POP	DE
	POP	AF
	CALL	PUTPTR
	JR	EXEC_XEQGO1
;
EXEC_PAGEV:	CALL	EXEC_EQUALS
	CALL	EXPRI
	EXX
	LD	L,0
	LD	(PAGE),HL
	JR	EXEC_XEQGO1
;
EXEC_TIMEV:	CP	'$'
	JR	Z,EXEC_TIMEVS
	CALL	EXEC_EQUALS
	CALL	EXPRI
	PUSH	HL
	EXX
	POP	DE
	CALL	PUTIME
	JR	EXEC_XEQGO1
;
EXEC_TIMEVS:	INC	IY			;SKIP '$'
	CALL	EXEC_EQUALS
	CALL	EXPRS
	CALL	PUTIMS
	JR	EXEC_XEQGO1
;
EXEC_LOMEMV:	CALL	EXEC_EQUALS
	CALL	EXPRI
	CALL	CLEAR
	EXX
	LD	(LOMEM),HL
	LD	(FREE),HL
	JR	EXEC_XEQGO1
;
EXEC_HIMEMV:	CALL	EXEC_EQUALS
	CALL	EXPRI
	EXX
	LD	DE,(FREE)
	INC	D
	XOR	A
	SBC	HL,DE
	ADD	HL,DE
	JP	C,ERROR			;"No room"
	LD	DE,(HIMEM)
	LD	(HIMEM),HL
	EX	DE,HL
	SBC	HL,SP
	JP	NZ,XEQ
	EX	DE,HL
	LD	SP,HL			;LOAD STACK POINTER
EXEC_XEQGO1:	JP	XEQ
;
;WIDTH expr
;
EXEC_WIDTHV:	CALL	EXPRI
	EXX
	LD	A,L
	LD	(WIDTH),A
	JR	EXEC_XEQGO1
;
;TRACE ON
;TRACE OFF
;TRACE line
;
EXEC_TRACE:	INC	IY
	LD	HL,0
	CP	EXEC_TON
	JR	Z,EXEC_TRACE0
	CP	EXEC_TOFF
	JR	Z,EXEC_TRACE1
	DEC	IY
	CALL	EXPRI
	EXX
EXEC_TRACE0:	DEC	HL
EXEC_TRACE1:	LD	(TRACEN),HL
	JR	EXEC_XEQGO1
;
;VDU expr,expr;....[|]
;
EXEC_VDU:	CALL	EXPRI
	EXX
	LD	A,L
	LD	B,1
EXEC_VDU1:	CALL	OSWRCH
	DJNZ	EXEC_VDU1
	LD	A,(IY)
	CP	'|'
	JR	Z,EXEC_VDU4
	CP	','
	JR	Z,EXEC_VDU2
	CP	';'
	JR	NZ,EXEC_VDU3
	LD	A,H
	CALL	OSWRCH
EXEC_VDU2:	INC	IY
EXEC_VDU3:	CALL	TERMQ
	JR	NZ,EXEC_VDU
	JR	EXEC_XEQGO1
;
EXEC_VDU4:	INC	IY
	XOR	A
	LD	B,9
	JR	EXEC_VDU1
;
;CLOSE channel number
;
EXEC_CLOSE:	CALL	CHANEL
	CALL	OSSHUT
	JR	EXEC_XEQGO1
;
;BPUT #channel,byte
;BPUT #channel,string[;]
;
EXEC_BPUT:	CALL	CHANEL			;CHANNEL NUMBER
	PUSH	DE
	CALL	COMMA
	CALL	EXPR
	EX	AF,AF'
	JP	M,EXEC_BPUTS
	CALL	SFIX
	EXX
	LD	A,L
	POP	DE
EXEC_BPUT1:	CALL	OSBPUT
EXEC_BPUTX:	JR	EXEC_XEQGO1
;
EXEC_BPUTS:	LD	A,E
	POP	DE
	LD	D,A
	LD	HL,ACCS
	OR	A
	JR	Z,EXEC_BPUTS0
EXEC_BPUTS1:	LD	A,(HL)
	INC	HL
	CALL	OSBPUT
	DEC	D
	JR	NZ,EXEC_BPUTS1
EXEC_BPUTS0:	CALL	NXT
	CP	';'
	LD	A,EXEC_LF
	JR	NZ,EXEC_BPUT1
	INC	IY
	JR	EXEC_BPUTX
;
;CALL address[,var[,var...]]
;
EXEC_CALL:	CALL	EXPRI			;ADDRESS
	EXX
	PUSH	HL			;SAVE IT
	LD	B,0			;PARAMETER COUNTER
	LD	DE,BUFFER		;VECTOR
EXEC_CALL1:	CALL	NXT
	CP	','
	JR	NZ,EXEC_CALL2
	INC	IY
	INC	B
	CALL	NXT
	PUSH	BC
	PUSH	DE
	CALL	VAR
	POP	DE
	POP	BC
	INC	DE
	LD	(DE),A			;PARAMETER TYPE
	INC	DE
	EX	DE,HL
	LD	(HL),E			;PARAMETER ADDRESS
	INC	HL
	LD	(HL),D
	EX	DE,HL
	JR	EXEC_CALL1
EXEC_CALL2:	LD	A,B
	LD	(BUFFER),A		;PARAMETER COUNT
	POP	HL			;RESTORE ADDRESS
	CALL	EXEC_USR1
	JP	XEQ
;
;USR(address)
;
USR:	CALL	ITEMI
	EXX
EXEC_USR1:	PUSH	HL			;ADDRESS ON STACK
	EX	(SP),IY
	INC	H			;PAGE &FF?
	LD	HL,EXEC_USR2			;RETURN ADDRESS
	PUSH	HL
	LD	IX,STAVAR
	CALL	Z,OSCALL		;INTERCEPT PAGE &FF
	LD	C,(IX+24)
	PUSH	BC
	POP	AF			;LOAD FLAGS
	LD	A,(IX+4)		;LOAD Z80 REGISTERS
	LD	B,(IX+8)
	LD	C,(IX+12)
	LD	D,(IX+16)
	LD	E,(IX+20)
	LD	H,(IX+32)
	LD	L,(IX+48)
	LD	IX,BUFFER
	JP	(IY)			;OFF TO USER ROUTINE
EXEC_USR2:	POP	IY
	XOR	A
	LD	C,A
	RET
;
; LEFT$(A$[,N]) = string
; MID$(A$,N[,M]) = string
; RIGHT$(A$[,N]) = string
;
EXEC_LEFTSL:	CALL	EXEC_GETSTR
	LD	HL,0FF00H		;Default all but last
	JR	NZ,EXEC_MIDSL1
	JR	EXEC_MIDSL0
;
EXEC_RITESL:	CALL	EXEC_GETSTR
	LD	HL,0FFFFH		;Default last char only
	JR	NZ,EXEC_MIDSL1
	JR	EXEC_MIDSL0
;
EXEC_MIDSL:	CALL	EXEC_GETSTR
	LD	A,5
	JP	NZ,ERROR		;'Missing comma'
	INC	IY
	PUSH	IX
	CALL	EXPRI
	POP	IX
	EXX
	CALL	NXT
	DEC	L
	LD	H,254			;Default rest of string
	CP	','
	JR	NZ,EXEC_MIDSL1
EXEC_MIDSL0:	INC	IY
	PUSH	HL
	PUSH	IX
	CALL	EXPRI
	POP	IX
	EXX
	LD	A,L
	POP	HL
	OR	A
	JR	Z,EXEC_MIDSL2		;Zero length
	DEC	A
	ADD	A,L
	LD	H,A
	JR	NC,EXEC_MIDSL1
	LD	A,L
	INC	A
	JR	Z,EXEC_MIDSL1
	LD	H,254
	JR	EXEC_MIDSL1
;
EXEC_MIDSL2:	LD	HL,1
EXEC_MIDSL1:	CALL	BRAKET
	CALL	EXEC_EQUALS
	PUSH	HL
	PUSH	IX
	CALL	EXPRS
	POP	IX
	POP	HL
	LD	C,E
	LD	B,(IX+0)
	LD	E,(IX+2)
	LD	D,(IX+3)
;
; Source string at ACCS, length C
; Destination string at DE, length B
; L = first character to modify 0-254
; H =  last character to modify 0-254
; IF L=255 THEN modify rightmost H + 2 chars
; ELSE IF H=255 modify all but last character
; ELSE IF L > H do nothing
; IX = destination VARPTR
;
	LD	A,L
	INC	A
	JR	NZ,EXEC_SUBSL1
	INC	H
	INC	H
	LD	A,C
	CP	H
	JR	NC,EXEC_SUBSL0
	LD	H,A
EXEC_SUBSL0:	LD	A,B
	SUB	H
	JR	NC,EXEC_SUBSL6
	XOR	A
EXEC_SUBSL6:	LD	L,A
	JR	EXEC_SUBSL5
;
EXEC_SUBSL1:	LD	A,H
	INC	A
	JR	NZ,EXEC_SUBSL2
	LD	A,B
	SUB	2
	JR	C,EXEC_SUBSL9
	LD	H,A
EXEC_SUBSL2:	LD	A,L
	CP	B
	JR	NC,EXEC_SUBSL9
	LD	A,H
	CP	B
	JR	C,EXEC_SUBSL3
EXEC_SUBSL5:	LD	A,B
	DEC	A
	LD	H,A
EXEC_SUBSL3:	LD	A,H
	SUB	L
	JR	C,EXEC_SUBSL9
	INC	A
	CP	C
	JR	C,EXEC_SUBSL4
	LD	A,C
EXEC_SUBSL4:	LD	B,0
	LD	H,B
	LD	C,A
	OR	A
	JR	Z,EXEC_SUBSL9
	EX	DE,HL
	ADD	HL,DE
	EX	DE,HL
	LD	HL,ACCS
	LDIR
EXEC_SUBSL9:	JP	XEQ
;
; EXIT FOR [var]
; EXIT REPEAT
; EXIT WHILE
;
EXEC_EXIT:	INC	IY			;Skip FOR/REPEAT/WHILE
	CP	EXEC_TFOR
	JR	NZ,EXEC_EXIT0
	LD	IX,0			;For EXIT FOR <var>
	CALL	TERMQ
	CALL	NZ,GETVAR
	LD	A,EXEC_TFOR
EXEC_EXIT0:	LD	D,1			;Level for WSRCH
	LD	E,A
EXEC_EXIT1:	LD	A,E
	POP	BC			;Marker
	LD	HL,EXEC_FORCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_EXIT4
	LD	HL,EXEC_REPCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_EXIT6
	LD	HL,EXEC_WHICHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_EXIT7
	PUSH	BC			;Put back marker
	PUSH	IX
	POP	BC
	EXX
	LD	A,3
	CALL	EXEC_RESLOC
	EXX
	PUSH	BC
	POP	IX
	JR	NZ,EXEC_EXIT1
	LD	A,44
	JP	ERROR			;'Bad EXIT'
;
EXEC_EXIT4:	POP	BC			;VARPTR
	LD	HL,14			;Skip text pointer, limit & step
	ADD	HL,SP
	LD	SP,HL			;Pop FOR record
	CP	EXEC_TFOR
	JR	NZ,EXEC_EXIT1
	PUSH	IX
	POP	HL
	LD	A,H
	OR	L
	JR	Z,EXEC_EXIT5
	SBC	HL,BC
EXEC_EXIT5:	LD	BC,EXEC_TFOR+EXEC_TNEXT*256
	JR	Z,EXEC_EXIT8
	INC	D			;Count nested FOR loops
	JR	EXEC_EXIT1
;
EXEC_EXIT6:	POP	BC			;Text pointer
	CP	EXEC_TREPEAT
	JR	NZ,EXEC_EXIT1
	LD	BC,EXEC_TREPEAT+EXEC_TUNTIL*256
	JR	EXEC_EXIT8
;
EXEC_EXIT7:	POP	BC			;Text pointer
	CP	EXEC_TWHILE
	JR	NZ,EXEC_EXIT1
	LD	BC,EXEC_TWHILE+EXEC_TENDWHILE*256
EXEC_EXIT8:	CALL	EXEC_WSRCH
	CALL	EXEC_SPAN			;Skip UNTIL expression
	JP	XEQ
;
;PUT port,data
;
EXEC_PUT:	CALL	EXPRI			;PORT ADDRESS
	EXX
	PUSH	HL
	CALL	COMMA
	CALL	EXPRI			;DATA
	EXX
	POP	BC
	OUT	(C),L			;OUTPUT TO PORT BC
	JP	XEQ
;
;SUBROUTINES:
;
;ASSIGN - Assign a numeric value to a variable.
;Outputs: NC,  Z     - OK, numeric scalar
;         NC, NZ, PE - OK, string array  (D = type, E = operator)
; else if NC, NZ, P  - OK, numeric array (D = type, E = operator)
; else if NC, NZ     - OK, string scalar
;          C, NZ     - illegal / invalid
;
EXEC_ASSIGN:	CALL	GETVAR			;VARIABLE
	RET	C			;ILLEGAL VARIABLE
	CALL	NZ,PUTVAR
	LD	D,A			;Type
	CALL	NXT
	INC	IY
	LD	E,A			;Operator (or =)
	CP	'='
	CALL	NZ,EXEC_EQUALS
	LD	A,D
	AND	11000000B	
	RET	NZ			;String or array
	PUSH	DE
	PUSH	HL
	CALL	EXPRN
	POP	IX
	POP	DE
;
; Falls through to...
;
; MODIFY - Update numeric variable according to operator:
;   Inputs: D = type
;           E = operator
;           HLH'L'C = value
;           IX = destination VARPTR
; Destroys: Everything except IX,IY,SP
; 
MODIFY:	LD	A,E
	CP	'='
	JR	Z,EXEC_STORE0		;Simple assignment
	PUSH	DE
	EXX
	EX	DE,HL
	EXX
	EX	DE,HL
	LD	B,C
	EX	(SP),HL
	LD	A,H
	EX	(SP),HL
	CALL	LOADN
	EX	(SP),HL
	LD	A,L
	EX	(SP),HL
	AND	15
	PUSH	IX
	CALL	FPP
	POP	IX
	POP	DE
	JR	C,EXEC_ERRORC
EXEC_STORE0:	LD	A,D			;Type
STOREN:	CP	5
	JR	Z,STORE5
	PUSH	AF
	INC	C			;SPEED - & PRESERVE F'
	DEC	C			; WHEN CALLED BY FNEND0
	CALL	NZ,SFIX			;CONVERT TO INTEGER
	POP	AF
	CP	4
	JR	Z,STORE4
	CP	A			;SET ZERO
EXEC_STORE1:	EXX
	LD	(IX+0),L
	EXX
	RET
;
STORE5:	LD	(IX+4),C
STORE4:	EXX
	LD	(IX+0),L
	LD	(IX+1),H
	EXX
	LD	(IX+2),L
	LD	(IX+3),H
	RET
;
; MODIFS - Update string variable according to operator:
;   Inputs: H = type
;           L = operator (= or +)
;           E = string length (string in accumulator)
;           IX = destination VARPTR
; Destroys: Everything except SP, IY
;
MODIFS:	LD	A,L			;Operator
	CP	'+'
	LD	A,H			;Type
	JR	NZ,STACCS
	PUSH	IX
	EX	(SP),IY
	CALL	PUSHS
	PUSH	IY
	POP	IX
	CALL	LOADS
	POP	BC
	LD	A,E
	ADD	A,C
	LD	A,19			;String too long
EXEC_ERRORC:	JR	C,EXEC_ERROR6
	LD	A,B			;Type
	INC	C
	DEC	C
	JR	Z,EXEC_MODFS1		;Zero length
	LD	HL,0
	LD	B,H
	ADD	HL,SP
	LDIR
	LD	SP,HL
EXEC_MODFS1:	POP	IY
;
; Falls through to:
;
STACCS:	LD	HL,ACCS
EXEC_STORES:	RRA
	JR	NC,EXEC_STORS3		;FIXED STRING
	PUSH	HL
	CALL	LOAD4
	LD	A,E			;LENGTH OF STRING
	EXX
	LD	L,A
	LD	A,H			;LENGTH ALLOCATED
	EXX
	CP	E
	JR	NC,EXEC_STORS1		;ENOUGH ROOM
	EXX
	LD	H,L
	EXX
	PUSH	HL
	LD	B,0
	LD	C,A
	ADD	HL,BC
	LD	BC,(FREE)
	SBC	HL,BC			;IS STRING LAST?
	POP	HL
	JR	Z,EXEC_STORS0
	LD	H,B
	LD	L,C			;DESTINATION
;
	OR	A			;V5 optimisation
	JR	Z,EXEC_STORS0
	LD	A,E
EXEC_STORS2:	LD	E,A
	DEC	E
	AND	E
	JR	NZ,EXEC_STORS2
	SCF
	RL	E
	LD	A,E
	EXX
	LD	H,A
	EXX
;
EXEC_STORS0:	SCF
EXEC_STORS1:	CALL	STORE4			;PRESERVES CARRY!
	LD	B,0
	LD	C,E
	EX	DE,HL
	POP	HL
	DEC	C
	INC	C
	RET	Z			;NULL STRING
	LDIR
	RET	NC			;STRING REPLACED
	LD	(FREE),DE
CHECK:	PUSH	HL
	LD	HL,(FREE)
	INC	H
	SBC	HL,SP
	POP	HL
	RET	C
	XOR	A
EXEC_ERROR6:	JP	ERROR			;"No room"
;
EXEC_STORS3:	LD	C,E
	PUSH	IX
	POP	DE
	XOR	A
	LD	B,A
	CP	C
	JR	Z,EXEC_STORS5
	LDIR
EXEC_STORS5:	LD	A,EXEC_CR
	LD	(DE),A
	RET
;
; SAVRET - SAVE 'RETURNed' PARAMETER INFO
;
EXEC_SAVRET:	LD	(IX+0),L			;Formal VARPTR
	LD	(IX+1),H
	LD	(IX+2),A
	EX	(SP),IY
	PUSH	AF
	PUSH	IY
	PUSH	IX
	CALL	NXT
	CALL	VAR
	POP	IX
	LD	(IX+4),L			;Actual VARPTR
	LD	(IX+5),H
	LD	(IX+6),A
	POP	IY
	POP	AF
	LD	BC,8
	ADD	IX,BC
	JR	EXEC_ARGUE0
;
;ARGUE: TRANSFER FN OR PROC ARGUMENTS FROM THE
; CALLING STATEMENT TO THE DUMMY VARIABLES VIA
; THE STACK.  IT MUST BE DONE THIS WAY TO MAKE
; PROCFRED(A,B)    DEF PROCFRED(B,A)     WORK.
;   Inputs: DE addresses parameter list 
;           IY addresses dummy variable list
;           IX addresses RETURNed parameter data block
;  Outputs: DE,IY updated
; Destroys: Everything
;
EXEC_ARGUE:	LD	A,-1
	PUSH	AF			;PUT MARKER ON STACK
EXEC_ARGUE1:	INC	IY			;BUMP PAST ( OR ,
	INC	DE
	PUSH	DE
	LD	B,0
	CALL	NXT
	CP	EXEC_TRETURN
	JR	NZ,EXEC_ARGUE9
	INC	IY			;SKIP 'RETURN'
	CALL	NXT
	INC	B			;FLAG 'RETURN'
EXEC_ARGUE9:	PUSH	BC
	PUSH	IX
	CALL	GETVAR			;FORMAL PARAMETER
	JR	C,EXEC_ARGERR
	CALL	NZ,PUTVAR
	POP	IX
	POP	BC
	POP	DE
	PUSH	HL			;VARPTR
	PUSH	AF
	PUSH	DE
	DEC	B
	JR	Z,EXEC_SAVRET
	EX	(SP),IY
EXEC_ARGUE0:	BIT	6,A			;ARRAY?
	JR	NZ,EXEC_ARGUE3
	OR	A			;TYPE
	JP	M,EXEC_ARGUE2		;STRING
	PUSH	IX
	CALL	EXPRN			;ACTUAL PARAMETER
	POP	IX
	EX	(SP),IY
	POP	DE
	POP	AF
	EXX
	PUSH	HL
	EXX
	PUSH	HL
	LD	B,A
	PUSH	BC
	JR	EXEC_ARGUE4
;
EXEC_ARGUE2:	PUSH	IX
	CALL	EXPRS
	EXX
	POP	BC
	EX	(SP),IY
	POP	DE
	EXX
	POP	AF
	CALL	PUSHS
	EXX
	PUSH	BC
	POP	IX
EXEC_ARGUE4:	CALL	NXT
	CP	','
	JR	NZ,EXEC_ARGUE5
	LD	A,(DE)
	CP	','
	JR	Z,EXEC_ARGUE1		;ANOTHER
EXEC_ARGERR:	LD	A,31
	JP	ERROR			;"Bad arguments"
;
EXEC_ARGUE3:	PUSH	IX
	CALL	NXT
	CALL	GETVAR
	JR	C,EXEC_ARGERR
	LD	C,(IX+0)
	LD	B,(IX+1)
	POP	IX
	CALL	NXT
	EX	(SP),IY
	POP	DE
	POP	AF
	PUSH	BC			;STACK ARRAY POINTER
	PUSH	AF			;STACK TYPE
	JR	EXEC_ARGUE4
;
EXEC_ARGUE5:	CALL	BRAKET
	LD	A,(DE)
	CP	')'
	JR	NZ,EXEC_ARGERR
	INC	DE
EXEC_UNSTAK:	EXX
EXEC_ARGUE6:	POP	BC
	LD	A,B
	INC	A
	EXX
	RET	Z			;MARKER POPPED
	EXX
	DEC	A
	BIT	6,A			;ARRAY
	JR	NZ,EXEC_ARGUE8
	OR	A
	JP	M,EXEC_ARGUE7		;STRING
	POP	HL
	EXX
	POP	HL
	EXX
	POP	IX
	CALL	STOREN			;WRITE TO DUMMY
	JR	EXEC_ARGUE6
;
EXEC_ARGUE7:	CALL	POPS
	POP	IX
	CALL	STACCS
	JR	EXEC_ARGUE6
;
EXEC_ARGUE8:	POP	BC			;ARRAY POINTER
	POP	IX
	LD	(IX+0),C
	LD	(IX+1),B
	JR	EXEC_ARGUE6
;
;Restore RETURNed parameters, via the stack to ensure that
; PROCFRED(A,B)    DEF PROCFRED(RETURN B,RETURN A)  works.
;
EXEC_RETXFR:	LD	A,-1
	PUSH	AF			;PUT MARKER ON STACK
EXEC_RETXF1:	EXX
	LD	L,(IX+4)		;Actual parameter (destination)
	LD	H,(IX+5)
	PUSH	HL			;STACK VARPTR
	LD	L,(IX+0)		;Formal parameter (source)
	LD	H,(IX+1)
	LD	A,(IX+2)
	BIT	6,A			;ARRAY?
	JR	NZ,EXEC_RETXF3
	OR	A			;TYPE
	JP	M,EXEC_RETXF2		;STRING
	PUSH	HL
	EX	(SP),IX
	CALL	LOADN
	POP	IX
	EXX	;STACK VALUE
	PUSH	HL
	EXX
	PUSH	HL
EXEC_RETXF6:	LD	B,(IX+6)
	PUSH	BC			;TYPE & EXPONENT
EXEC_RETXF5:	CALL	CHECK			;CHECK ROOM
	JR	EXEC_RETXF4
;
EXEC_RETXF3:	LD	E,(HL)
	INC	HL
	LD	D,(HL)
	PUSH	DE			;STACK ARRAY POINTER
	JR	EXEC_RETXF6
;
EXEC_RETXF2:	PUSH	HL
	EX	(SP),IX
	CALL	LOADS
	POP	IX
	LD	A,(IX+6)
	EXX
	PUSH	IX
	POP	HL
	EXX
	CALL	PUSHS
	EXX
	PUSH	HL
	POP	IX
	EXX
EXEC_RETXF4:	LD	DE,8
	ADD	IX,DE
	EXX
	DJNZ	EXEC_RETXF1
	JP	EXEC_UNSTAK
;
;Restore 'RETURNed' parameters, 
;
EXEC_RESRET:	POP	BC			;B = 'RETURN' COUNT
	LD	H,0
	LD	L,B
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,HL			;RETURN COUNT * 8
	ADD	HL,SP
	LD	IX,0
	ADD	IX,SP			;ADDRESS PARAMETER LIST
	PUSH	AF
	PUSH	DE
	PUSH	HL
	EXX
	PUSH	BC
	PUSH	DE
	EXX
	LD	A,B
	LD	HL,ACCS
	LD	DE,BUFFER
	LD	BC,255
	LDIR
	LD	B,A
	CALL	EXEC_RETXFR			;TRANSFER VIA STACK
	LD	HL,BUFFER
	LD	DE,ACCS
	LD	BC,255
	LDIR
	EXX
	POP	DE
	POP	BC
	EXX
	POP	HL
	POP	DE
	POP	AF
	JR	EXEC_RESAR1
;
; Restore LOCAL array or memory block:
;
EXEC_RESARR:	POP	BC
	BIT	7,B			;String array?
	POP	HL
	POP	BC
	ADD	HL,BC
	ADD	HL,SP
	CALL	NZ,EXEC_FREESA		;Free string array
EXEC_RESAR1:	LD	SP,HL
	INC	IX			;Flag something restored
	JR	EXEC_RESLO1
;
; RESLOC - Restore local variables/arrays or DATA/ERROR status from stack
;   Inputs: A = 0 if everything OK, bit0 set if DATPTR, bit1 set if ERRTRP
;  Outputs: Z if nothing was restored, NZ if something was restored
; Destroys: A,B,C,D,E,H,L,H',L',IX,SP,flags
;
EXEC_RESLOC:	POP	DE			;Return address
	LD	IX,0			;To flag nothing was restored
EXEC_RESLO1:	POP	BC			;Marker ?
	LD	HL,EXEC_LOCCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_RESLO2		;Something to restore
	OR	A
	JR	NZ,EXEC_RESLO8
	LD	HL,EXEC_RETCHK
	SBC	HL,BC
	JR	Z,EXEC_RESRET
	LD	HL,EXEC_ARRCHK
	OR	A
	SBC	HL,BC
	JR	Z,EXEC_RESARR
EXEC_RESLO8:	PUSH	IX
	POP	HL
	LD	A,H
	OR	L
EXEC_RESLO0:	PUSH	BC			;Put back marker
	EX	DE,HL
	JP	(HL)			;Return
;
EXEC_RESLO2:	POP	IX			;Variable pointer
	OR	A
	JR	Z,EXEC_RESLO3		;Everything allowed
	PUSH	IX
	POP	BC
	BIT	0,A
	JR	Z,EXEC_RESLO6		;Bit 0 set, so
	LD	HL,DATPTR		;test for DATPTR
	SBC	HL,BC
	JR	Z,EXEC_RESLO3
EXEC_RESLO6:	OR	A
	BIT	1,A
	JR	Z,EXEC_RESLO7		;Bit 1 set, so
	LD	HL,ERRTRP		;test for ERRPTR
	SBC	HL,BC
	JR	Z,EXEC_RESLO3
EXEC_RESLO7:	PUSH	BC			;Put back pointer
	LD	BC,EXEC_LOCCHK
	JR	EXEC_RESLO0
;
EXEC_RESLO3:	POP	BC			;Type / exponent
	BIT	6,B
	JR	NZ,EXEC_RESLO4		;Array?
	BIT	7,B
	JR	NZ,EXEC_RESLO5		;String?
	POP	HL
	EXX
	POP	HL
	EXX
	BIT	4,B
	JR	NZ,EXEC_RESLO1
	PUSH	AF
	LD	A,B
	CALL	STOREN			;Numeric
	POP	AF
	JR	EXEC_RESLO1
;
EXEC_RESLO4:	POP	HL
	BIT	4,B
	JR	NZ,EXEC_RESLO1
	LD	(IX+0),L		;Array
	LD	(IX+1),H
	JR	EXEC_RESLO1
;
EXEC_RESLO9:	LD	B,0
	ADD	HL,BC
	LD	SP,HL
EXEC_RESLGO:	JR	EXEC_RESLO1
;
EXEC_RESLO5:	LD	HL,0
	ADD	HL,SP
	BIT	4,B
	JR	NZ,EXEC_RESLO9
	PUSH	AF
	PUSH	DE
	LD	E,C
	LD	A,B
	CALL	EXEC_STORES			;String
	POP	DE
	POP	AF
	LD	SP,HL
	JR	EXEC_RESLGO
;
;SAVLOC: SUBROUTINE TO STACK LOCAL PARAMETERS
;  OF A FUNCTION OR PROCEDURE.
;THERE IS A LOT OF STACK MANIPULATION - CARE!!
;   Inputs: IY is parameters pointer
;  Outputs: IY updated
;           A' incremented for each RETURN
; Destroys: A',A,B,C,D,E,H,L,IX,IY,F,SP
;
EXEC_SAVLOC:	POP	DE			;RETURN ADDRESS
EXEC_SAVLO1:	INC	IY			;BUMP PAST ( OR ,
	CALL	NXT
	CP	EXEC_TRETURN
	JR	NZ,EXEC_SAVLO6
	EX	AF,AF'
	INC	A			;RETURN counter
	EX	AF,AF'
	INC	IY			;Bump past RETURN
	CALL	NXT
EXEC_SAVLO6:	PUSH	DE
	EXX
	PUSH	BC
	PUSH	DE
	PUSH	HL
	EXX
	CALL	VAR			;DUMMY VARIABLE
	EXX
	POP	HL
	POP	DE
	POP	BC
	EXX
	POP	DE
	BIT	6,A			;ARRAY?
	JR	NZ,EXEC_SAVLO3
	OR	A			;TYPE
	JP	M,EXEC_SAVLO2		;STRING
	EXX
	PUSH	HL			;SAVE H'L'
	EXX
	LD	B,A			;TYPE
	CALL	LOADN
	EXX
	EX	(SP),HL
	EXX
	PUSH	HL
	PUSH	BC
	JR	EXEC_SAVLO4
;
EXEC_SAVLO3:	LD	C,(IX+0)		;ARRAY POINTER
	LD	B,(IX+1)
	PUSH	BC			;SAVE TO STACK
	PUSH	AF			;SAVE TYPE
	JR	EXEC_SAVLO4
;
EXEC_SAVLO2:	PUSH	AF			;STRING TYPE
	PUSH	DE
	EXX
	PUSH	HL
	EXX
	CALL	LOADS
	EXX
	POP	HL
	EXX
	LD	C,E
	POP	DE
	CALL	CHECK
	POP	AF			;LEVEL STACK
	LD	HL,0
	LD	B,L
	SBC	HL,BC
	ADD	HL,SP
	LD	SP,HL
	LD	B,A			;TYPE
	PUSH	BC
	JR	Z,EXEC_SAVLO4
	PUSH	DE
	LD	DE,ACCS
	EX	DE,HL
	LD	B,L
	LDIR	;SAVE STRING ON STACK
	POP	DE
EXEC_SAVLO4:	PUSH	IX			;VARPTR
	CALL	EXEC_SAVLO5
EXEC_LOCCHK:	EQU	$
EXEC_SAVLO5:	CALL	CHECK
	CALL	NXT
	CP	','			;MORE?
	JR	Z,EXEC_SAVLO1
	EX	DE,HL
	JP	(HL)			;"RETURN"
;
TERMQ:	CALL	NXT
	CP	EXEC_TELSE
	RET	NC
	CP	':'			;ASSEMBLER SEPARATOR
	RET	NC
	CP	EXEC_CR
	RET
;
EXEC_SPAN:	CALL	TERMQ
	RET	Z
	INC	IY
	CP	'"'
	CALL	Z,EXEC_QUOTE
	JR	EXEC_SPAN
;
EXEC_EQUALS:	CALL	NXT
	INC	IY
	CP	'='
	RET	Z
	LD	A,4
	JP	ERROR			;"Mistake"
;
EXEC_FORMAT:	CP	EXEC_TTAB
	JR	Z,EXEC_DOTAB
	CP	EXEC_TSPC
	JR	Z,EXEC_DOSPC
	CP	''''
	RET	NZ
	CALL	CRLF
	XOR	A
	RET
;
EXEC_DOTAB:	PUSH	BC
	CALL	EXPRI
	EXX
	POP	BC
	LD	A,(IY)
	CP	','
	JR	Z,EXEC_DOTAB1
	CALL	BRAKET
	LD	A,L
TABIT:	LD	HL,COUNT
	CP	(HL)
	RET	Z
	PUSH	AF
	CALL	C,CRLF
	POP	AF
	SUB	(HL)
	JR	SPACES
EXEC_DOTAB1:	INC	IY
	PUSH	BC
	PUSH	HL
	CALL	EXPRI
	EXX
	POP	DE
	POP	BC
	CALL	BRAKET
	CALL	PUTCSR
	XOR	A
	RET
;
EXEC_DOSPC:	PUSH	BC
	CALL	ITEMI
	EXX
	LD	A,L
	POP	BC
SPACES:	OR	A
	RET	Z
	PUSH	BC
	LD	B,A
EXEC_FILL1:	LD	A,' '
	CALL	OUTCHR
	DJNZ	EXEC_FILL1
	POP	BC
	XOR	A
	RET
;
EXEC_PTEXT:	LD	HL,ACCS
	INC	E
EXEC_PTEXT1:	DEC	E
	RET	Z
	LD	A,(HL)
	INC	HL
	CALL	OUTCHR
	JR	EXEC_PTEXT1
;
EXEC_FETCHS:	PUSH	AF
	PUSH	BC
	PUSH	HL
	EX	(SP),IY
	CALL	EXEC_XTRACT
	CALL	NXT
	EX	(SP),IY
	POP	HL
	POP	BC
	POP	AF
	RET
;
EXEC_LINES:	LD	DE,ACCS
EXEC_LINE1S:	LD	A,(HL)
	LD	(DE),A
	CP	EXEC_CR
	RET	Z
	INC	HL
	INC	E
	JR	EXEC_LINE1S
;
EXEC_XTRACT:	CALL	NXT
	CP	'"'
	INC	IY
	JP	Z,CONS
	DEC	IY
	LD	DE,ACCS
EXEC_XTRAC1:	LD	A,(IY)
	LD	(DE),A
	CP	','
	RET	Z
	CP	EXEC_CR
	RET	Z
	INC	IY
	INC	E
	JR	EXEC_XTRAC1
;
EXEC_DSRCH:	LD	A,EXEC_TDATA
EXEC_SEARCH:	LD	B,0
EXEC_SRCH1:	LD	C,(HL)
	INC	C
	DEC	C
	JR	Z,EXEC_SRCH2			;FAIL
	INC	HL
	INC	HL
	INC	HL
	CP	(HL)
	RET	Z
	DEC	C
	DEC	C
	DEC	C
	ADD	HL,BC
	JP	EXEC_SRCH1
EXEC_SRCH2:	DEC	HL			;POINT TO CR
	SCF
	RET
;
; NSCAN - scan for token at start of line, with nesting of inner structures
; Alternative entry at NSCAN1 with L = level (used by CASE)
;
;   Inputs: B = token to find (1, start of line)
;           C = token to find (2, start of line)
;           E = token to nest (end of line)
;           D = token to unnest (start of line)
;           IY = start search area (line length byte)
;  Outputs: NZ if not found
;           Z if found, IY points to byte after token
; Destroys: A,B,C,L,IY,F
;
EXEC_NSCAN:	LD	L,0			;nest level
EXEC_NSCAN1:	LD	A,(IY)			;get line length
	OR	A			;test zero = end of prog
	JR	Z,EXEC_NSCAN6
	LD	A,(IY+3)		;initial token
	CP	B			;test value reqd
	JR	Z,EXEC_NSCAN3		;found (1)
	CP	C
	JR	Z,EXEC_NSCAN3		;found (2)
EXEC_NSCAN7:	CP	D			;unnest?
	JR	Z,EXEC_NSCAN5
EXEC_NSCAN2:	PUSH	BC
	LD	B,0
	LD	C,(IY)
	ADD	IY,BC			;go to next line
	LD	A,(IY-2)
	CP	E			;nest?
	LD	A,C	
	POP	BC
	JR	NZ,EXEC_NSCAN1		;continue
	CP	5			;empty line ?
	JR	C,EXEC_NSCAN1		;continue
	INC	L			;increment nest level
	JR	EXEC_NSCAN1			;continue
;
EXEC_NSCAN3:	INC	L
	DEC	L
	JR	NZ,EXEC_NSCAN7
EXEC_NSCAN4:	LD	BC,4
	ADD	IY,BC
	XOR	A			;Z
	RET
;
EXEC_NSCAN5:	DEC	L			;decrement nest level
	JP	P,EXEC_NSCAN2
	JR	EXEC_NSCAN4
;
EXEC_NSCAN6:	OR	1			;NZ
	RET
;
; WSRCH - search for token, with nesting of inner structures
;
;   Inputs: B = token to find or unnest (anywhere)
;           C = token to nest (anywhere), ignore after EXIT
;           D = ordinal (1 = find first token, 2 = second)
;           IY = address to start looking
;  Outputs: IY points to byte after that found
;           if not found abort to END
; Destroys: A,D,IY,F
;
EXEC_WSRCH:	LD	A,(IY)
	INC	IY
	CP	'"'
	CALL	Z,EXEC_QUOTE
	CP	EXEC_TREM
	JR	Z,EXEC_WSRCHM
	CP	EXEC_TEXIT
	JR	Z,EXEC_WSRCHE
	CP	B
	JR	Z,EXEC_WSRCHX
	CP	C
	JR	Z,EXEC_WSRCHP
	CP	EXEC_CR
	JR	NZ,EXEC_WSRCH
EXEC_WSRCH1:	LD	A,(IY)				;Line length
	INC	IY
	OR	A
	JP	Z,EXEC_END
	INC	IY
	INC	IY				;Skip line number
	LD	A,(IY)
	CP	EXEC_TDATA
	JR	NZ,EXEC_WSRCH
EXEC_WSRCHM:	LD	A,(IY)
	INC	IY
	CP	EXEC_CR
	JR	NZ,EXEC_WSRCHM			;Skip to end of line
	JR	EXEC_WSRCH1
;
EXEC_WSRCHP:	INC	D
	JR	EXEC_WSRCH
;
EXEC_WSRCHX:	DEC	D
	JR	NZ,EXEC_WSRCH
	RET
;
EXEC_WSRCHE:	CALL	NXT
	INC	IY
	JR	EXEC_WSRCH
;
; QUOTE - skip quoted string
;
EXEC_QUOTE:	LD	A,(IY)
	INC	IY
	CP	EXEC_CR
	JP	Z,EXEC_MISQUO
	CP	'"'
	JR	NZ,EXEC_QUOTE
	RET
;
EXEC_MISQUO:	LD	A,9
	JP	ERROR			;"Missing quote"
;
; X14OR5 - multiply by 1, 4 or 5
;   Inputs: DE = number to be multiplied
;           A = 1, 4 or 5 (else multiply by 4)
;  Outputs: DE = DE * A
;           Carry set if overflow
; Destroys: D,E,H,L,F
;
X14OR5:	LD	H,D
	LD	L,E
	CP	1
	RET	Z
	CP	5
	ADD	HL,HL
	RET	C
	ADD	HL,HL
	RET	C
	EX	DE,HL
	RET	NZ
	ADD	HL,DE
	EX	DE,HL
	RET
;
; MUL16 - 16-bit multiply
;   Inputs: HL = number to be multiplied
;           BC = multiplier
;  Outputs: HL = HL * BC
;           Carry set if overflow
; Destroys: A,D,E,H,L,F
;
MUL16:	EX	DE,HL
	LD	HL,0
	LD	A,16
EXEC_MUL161:	ADD	HL,HL
	RET	C			;OVERFLOW
	SLA	E
	RL	D
	JR	NC,EXEC_MUL162
	ADD	HL,BC
	RET	C
EXEC_MUL162:	DEC	A
	JR	NZ,EXEC_MUL161
	RET
;
CHANEL:	CALL	NXT
	CP	'#'
	LD	A,45
	JP	NZ,ERROR		;"Missing #"
CHNL:	INC	IY			;SKIP '#'
	CALL	ITEMI
	EXX
	EX	DE,HL
	RET
;
; FREESA - Free members of a string array if adjacent to the top of heap
;   Inputs: BC = length of array (= 4 * number of elements)
;           HL addresses array first byte *above* array
;  Outputs: NZ if any array element freed, Z if none
; Destroys: nothing
;
EXEC_FREESA:	PUSH	AF
EXEC_FREES0:	PUSH	BC
	PUSH	DE
	PUSH	HL
	XOR	A
	LD	D,B
	LD	E,C
	LD	B,A
EXEC_FREES1:	PUSH	DE
	DEC	HL
	LD	D,(HL)
	DEC	HL
	LD	E,(HL)
	DEC	HL
	LD	C,(HL)
	DEC	HL
	PUSH	HL
	LD	HL,(FREE)
	EX	DE,HL
	ADD	HL,BC
	SBC	HL,DE
	JR	NZ,EXEC_FREES2
	ADD	HL,DE
	SBC	HL,BC
	LD	(FREE),HL
	OR	H
EXEC_FREES2:	POP	DE
	POP	HL
	LD	C,4
	OR	A
	SBC	HL,BC
	EX	DE,HL
	JR	NZ,EXEC_FREES1
	OR	A
	POP	HL
	POP	DE
	POP	BC
	OR	A
	JR	NZ,EXEC_FREES0
	POP	AF
	RET
;

